<?php $isPrivate=($tour['program_type'] ?? 'fixed')==='private'; $old=session('booking_old') ?: []; ?>
<?php
$availability = tour_availability($tour);
$available = $availability['available'];
$bookable = $availability['bookable'];
$prices = $availability['prices'];
$groupSize = $availability['group_size'];
$fromPrice = $prices ? min($prices) : null;
$license = tour_license($settings);
$coverage = tour_coverage($tour);
foreach ($tour['itinerary'] as $dayIndex=>$dayRow) $tour['itinerary'][$dayIndex]['title'] = day_title($dayRow['title']);
$photos =array_merge([['path'=>$tour['cover'], 'caption'=>$tour['title']]], $tour['images']);
$dayPhotoIndexes=[];
foreach ($tour['itinerary'] as $dayIndex=>$dayPhoto) foreach (day_photos($dayPhoto) as $photoIndex=>$photo) { $dayPhotoIndexes[$dayIndex][$photoIndex]=count($photos); $photos[]=['path'=>$photo['path'],'caption'=>$photo['caption'] ?: $dayPhoto['title']]; }
$tripPhotoCount=count($photos);
$hotelPhotoIndexes=[];
foreach ($tour['itinerary'] as $dayIndex=>$dayRow) foreach (day_hotels($dayRow) as $hotelIndex=>$hotelRow) foreach ($hotelRow['images'] as $imageIndex=>$hotelImage) { $hotelPhotoIndexes[$dayIndex][$hotelIndex][$imageIndex]=count($photos); $photos[]=['path'=>$hotelImage,'caption'=>$hotelRow['name']]; }
$vehicleRows=\App\Support\VehicleOptions::decode($tour['vehicle_options'] ?? null);
$vehiclePhotoIndexes=[];
foreach ($vehicleRows as $vehicleIndex=>$vehicleRow) if (!empty($vehicleRow['image'])) { $vehiclePhotoIndexes[$vehicleIndex]=count($photos); $photos[]=['path'=>$vehicleRow['image'],'caption'=>\App\Support\VehicleOptions::label($vehicleRow)]; }

?>
<div class="trip-detail">

<?php if ($preview): ?><div class="preview-bar">ตัวอย่างโปรแกรม · <?= status_label($tour['status']) ?> · ยังส่งคำขอจองจากหน้านี้ไม่ได้ <a href="<?= (base_url() . ('admin/tours/'.$tour['id'])) ?>">กลับไปแก้ไข <i class="material-icons" aria-hidden="true">north_east</i></a></div><?php endif ?>
<div class="container detail-layout"><div class="detail-content"><div class="detail-heading"><div class="breadcrumb"><?php $detailChannel=program_channels()[tour_channel($tour)]; ?><a href="<?= e(base_url().$detailChannel['path']) ?>"><?= e($detailChannel['label']) ?></a><?php $route=!empty($tour['route_id']) ? app(\App\Repositories\DestinationRepository::class)->route($tour['route_id']) : null; if ($route && count($tour['destinations'])===1): foreach (app(\App\Repositories\DestinationRepository::class)->trail($route) as $place): ?><span>/</span><a href="<?= e(destination_url($place)) ?>"><?= e($place['name']) ?></a><?php endforeach; else: ?><span>/</span><?= e(implode(' · ',array_column($tour['countries'],'name'))) ?><?php endif ?></div><span class="eyebrow"><?= $isPrivate ? 'PRIVATE PACKAGE' : 'OVERSEAS TOUR' ?> · <?= e($tour['code']) ?></span><h1><?= e($tour['title']) ?></h1><div class="detail-meta"><span><i class="material-icons" aria-hidden="true">location_on</i> <?= e(implode(' → ',array_column($tour['destinations'],'name'))) ?></span><span><i class="material-icons" aria-hidden="true">schedule</i> <?= (int)$tour['days'] ?> วัน <?= (int)$tour['nights'] ?> คืน</span><span><i class="material-icons" aria-hidden="true">group</i> <?= $isPrivate ? ($groupSize ? 'กรุ๊ปส่วนตัว '.$groupSize.' คน' : 'แพ็คเกจส่วนตัว').' · เลือกวันเอง' : 'จองได้ตั้งแต่ 1 คน' ?></span><span><i class="material-icons" aria-hidden="true">flight</i> <?= e(flight_note($tour)) ?><?php $detailAirlines=$tour['flight_summary']['airlines'] ?? ($tour['airline']!=='' ? [$tour['airline']] : []); ?><?= !empty($tour['flight_included']) && $detailAirlines ? ' · '.e(implode(' / ',$detailAirlines)) : '' ?></span></div></div>
<div class="trip-visual" data-photo-group="<?= e(json_encode(range(0,$tripPhotoCount-1))) ?>">
 <div class="trip-gallery trip-gallery-<?= min(3,$tripPhotoCount) ?>">
 <?php foreach (array_slice($photos,0,min(3,$tripPhotoCount)) as $i=>$photo): ?><a class="trip-photo" href="<?= tour_image($photo['path']) ?>" data-photo="<?= $i ?>" aria-label="เปิดภาพ <?= e($photo['caption'] ?: $tour['title']) ?>"><img src="<?= tour_image($photo['path']) ?>" alt="<?= e($photo['caption'] ?: $tour['title']) ?>" width="<?= $i===0 ? 1200 : 600 ?>" height="<?= $i===0 ? 800 : 400 ?>" <?= $i===0 ? 'fetchpriority="high"' : 'loading="lazy"' ?>><span><?= $i===0 ? 'EXPLORE THE JOURNEY' : 'ดูภาพ' ?> <i class="material-icons" aria-hidden="true">north_east</i></span></a><?php endforeach ?>
 </div>
 <button class="trip-gallery-all" type="button" data-photo="0"><i class="material-icons" aria-hidden="true">photo_library</i> ดูภาพทั้งหมด · <?= $tripPhotoCount ?></button>
</div>
