<section id="experience"><span class="eyebrow">THE EXPERIENCE</span><h2>เรื่องราวของทริปนี้</h2><p class="preline"><?= e($tour['summary']) ?></p><div class="highlight-box"><h3>ไฮไลต์ที่ไม่อยากให้พลาด</h3><ul class="trip-highlights"><?php foreach (preg_split('/\R/u', $tour['highlights']) as $highlight): if (trim($highlight)==='') continue; ?><li><span><i class="material-icons" aria-hidden="true">north_east</i></span><?= e(trim($highlight)) ?></li><?php endforeach ?></ul></div></section><?php load_view('partials/tour_flights',['tour'=>$tour,'available'=>$available,'isPrivate'=>$isPrivate]); ?><?php load_view('partials/tour_destinations',['tour'=>$tour]); ?><section id="itinerary"><span class="eyebrow">YOUR DAY-BY-DAY JOURNEY</span><div class="trip-section-heading"><h2>แต่ละวัน มีอะไรให้ค้นพบ</h2><button type="button" class="trip-text-button" id="itinerary-toggle" aria-expanded="false">เปิดทุกวัน <i class="material-icons" aria-hidden="true">add</i></button></div><div class="itinerary"><?php foreach ($tour['itinerary'] as $i=>$day): ?><details <?= $i===0 ? 'open' : '' ?>><summary><span class="day-label">DAY <?= str_pad($i+1,2,'0',STR_PAD_LEFT) ?></span><?= e($day['title']) ?></summary><div><?php load_view('partials/day_gallery',['day'=>$day,'i'=>$i,'dayPhotoIndexes'=>$dayPhotoIndexes]); ?><p class="preline"><?= e($day['description']) ?></p><?php if ($day['hotel']): ?><p><b>ที่พัก:</b> <?= e($day['hotel']) ?></p><?php endif ?><?php load_view('partials/day_hotels',['day'=>$day,'i'=>$i,'hotelPhotoIndexes'=>$hotelPhotoIndexes]); ?><?php $dayMeals=array_filter(['breakfast'=>'เช้า','lunch'=>'กลางวัน','dinner'=>'เย็น'],fn($f)=>$day[$f]!==null,ARRAY_FILTER_USE_KEY); if ($dayMeals): ?><div class="day-meals"><b>มื้ออาหารวันนี้</b><div class="meal-row"><?php foreach ($dayMeals as $f=>$label): ?><div class="day-meal<?= $day[$f] ? ' is-included' : '' ?>"><i class="material-icons" aria-hidden="true"><?= $day[$f] ? 'check' : 'remove' ?></i><span><?= $label ?> <small><?= $day[$f] ? 'รวม' : 'ไม่รวม' ?></small></span></div><?php endforeach ?></div></div><?php endif ?></div></details><?php endforeach ?></div></section><?php load_view('partials/tour_vehicles',['vehicleRows'=>$vehicleRows,'vehiclePhotoIndexes'=>$vehiclePhotoIndexes,'isPrivate'=>$isPrivate]); ?><?php load_view($isPrivate ? 'partials/private_table' : 'partials/departure_table',['available'=>$available]); ?><?php load_view('partials/tour_coverage',['coverage'=>$coverage]); ?><?php load_view('partials/tour_know_before',['tour'=>$tour]); ?></div>
